def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    threat_scores = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            req = opp.get('water_requirement', WATER_REQ)
            obudget = opp.get('budget', 0)
            ohp = opp.get('hp', 0)
            ono = opp.get('no_water_days', 0)
            score = float(bid)
            if req >= WATER_REQ:
                score += 4.0
            if ohp <= 3 or ono >= 1:
                score += 6.0
            if obudget > budget:
                score += 3.0
            threat_scores.append(score)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_threat = max(threat_scores) if threat_scores else highest_prev

    scarcity = 0
    if supply <= 16:
        scarcity = 3
    elif supply <= 18:
        scarcity = 2
    elif supply <= 21:
        scarcity = 1

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if scarcity >= 3:
        base = max(72.0, highest_threat + 2.5)
    elif scarcity == 2:
        base = max(60.0, highest_prev + 1.5)
    elif scarcity == 1:
        base = max(46.0, highest_prev * 0.72)
    else:
        base = max(28.0, highest_prev * 0.48)

    if urgency >= 5:
        base = max(base, highest_threat + 4.0, 88.0)
    elif urgency >= 3:
        base = max(base, highest_prev + 2.0, 72.0)
    elif urgency >= 1:
        base = max(base, 52.0)

    if day >= 8 and hp > 5 and no_water_days == 0 and supply >= 20:
        base *= 0.82

    max_safe = budget
    if hp > 6 and no_water_days == 0:
        max_safe = min(max_safe, DAILY_SALARY * 1.1)
    elif hp > 3:
        max_safe = min(max_safe, DAILY_SALARY * 1.45)

    bid = min(base, max_safe)

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, highest_threat + 5.0, DAILY_SALARY * 1.2))

    if bid < 0:
        bid = 0.0

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents are alive, bid conservatively to ensure survival without overspending.
    if not alive_opponents:
        # Ensure we don't bid more than our current budget
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Decision logic based on yesterday's highest pressure and my current health
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If opponents were bidding very high yesterday
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # If I'm relatively healthy, I can afford to save money and let opponents overspend.
            if my_status['hp'] > 3:
                return min(my_status['budget'], DAILY_SALARY * 0.3)
            # If I'm not healthy, I need water despite high competition.
            return min(my_status['budget'], DAILY_SALARY * 0.95)

        # If opponents were not excessively aggressive, bid slightly higher than the highest previous bid,
        # ensuring a minimum competitive bid.
        return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))

    # Fallback strategy if no yesterday bids are available (e.g., first day or opponents didn't bid)
    # Prioritize survival if health is low.
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.9)
    # Otherwise, bid moderately to conserve budget while still aiming for water.
    return min(my_status['budget'], DAILY_SALARY * 0.55)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

    max_prev = max(yesterday_bids)
    avg_prev = sum(yesterday_bids) / len(yesterday_bids)

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max_prev + 5.0)

    if day_context['supply'] < 18:
        return min(my_status['budget'], max(avg_prev * 1.1, 75.0))

    return min(my_status['budget'], max(avg_prev, 60.0))
